WITH lines AS (SELECT id, plan, effective_from, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) e AS tier_value) SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, DATE_TRUNC('QUARTER', effective_from) AS quarter_start, CASE WHEN tier_value >= 89 THEN 'HIGH' ELSE 'LOW' END AS tier_value_tier, COUNT_IF(plan = 'enterprise') AS enterprise_events, SUM(CASE WHEN plan = 'starter' THEN tier_value ELSE 0 END) AS starter_tier_value, RANK() OVER (PARTITION BY DATE_TRUNC('YEAR', effective_from) ORDER BY SUM(CASE WHEN plan = 'starter' THEN tier_value ELSE 0 END) DESC) AS starter_tier_value_rank FROM lines GROUP BY year_start, quarter_start, tier_value_tier
